// FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE
// AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER
// LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM,
// OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE
// SOFTWARE.

namespace NativeMethods
{
    using System;
    using System.Runtime.InteropServices;

    internal static class SHELL32
    {
        private delegate int BrowseCallBackProc(IntPtr hWnd, int msg, IntPtr lParam, IntPtr wParam);

        [StructLayout(LayoutKind.Sequential, CharSet = CharSet.Unicode)]
        private struct BROWSEINFO
        {
            public IntPtr           Owner;
            public IntPtr           Root;
            public string           SelectedPath;
            public string           Description;
            public UInt32           Flags;
            public BrowseCallBackProc   Callback;
            public IntPtr           lParam;
            public Int32            Image;
        }

        private const Int32 MAX_PATH            = 260;
        private const Int32 BFFM_INITIALIZED        = 1;
        private const Int32 BFFM_SETEXPANDED        = 0x046A;
        private const string FOLDERID_ComputerFolder    = &quot;{0AC0837C-BBF8-452A-850D-79D08E667CA7}&quot;;

        [Flags]
        private enum BIF : UInt32
        {
            RETURNONLYFSDIRS    = 0x00000001,
            DONTGOBELOWDOMAIN   = 0x00000002,
            STATUSTEXT      = 0x00000004,
            RETURNFSANCESTORS   = 0x00000008,
            EDITBOX         = 0x00000010,
            VALIDATE        = 0x00000020,
            NEWDIALOGSTYLE      = 0x00000040,
            USENEWUI        = NEWDIALOGSTYLE | EDITBOX,
            BROWSEINCLUDEURLS   = 0x00000080,
            UAHINT          = 0x00000100,
            NONEWFOLDERBUTTON   = 0x00000200,
            NOTRANSLATETARGETS  = 0x00000400,
            BROWSEFORCOMPUTER   = 0x00001000,
            BROWSEFORPRINTER    = 0x00002000,
            BROWSEINCLUDEFILES  = 0x00004000,
            SHAREABLE       = 0x00008000,
            BROWSEFILEJUNCTIONS = 0x00010000
        }

        [DllImport(&quot;shell32.dll&quot;, CharSet = CharSet.Unicode)]
        private static extern IntPtr SHBrowseForFolder(ref BROWSEINFO lpbi);

        [DllImport(&quot;shell32.dll&quot;, CharSet = CharSet.Unicode)]
        private static extern bool SHGetPathFromIDList(IntPtr pidl, IntPtr pszPath);

        [DllImport(&quot;shell32.dll&quot;, CharSet = CharSet.Unicode)]
        private static extern Int32 SHILCreateFromPath(string pszPath, ref IntPtr pidl, IntPtr rgfInOut);

        [DllImport(&quot;shell32.dll&quot;, CharSet = CharSet.Unicode)]
        private static extern Int32 SHGetKnownFolderIDList(Guid rfid, UInt32 Flags, IntPtr Token, ref IntPtr pidl);

        [DllImport(&quot;user32.dll&quot;, CharSet = CharSet.Unicode)]
        private static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);

        private static int OnBrowseEvent(IntPtr hWnd, int msg, IntPtr lParam, IntPtr lpData)
        {
            switch (msg) {
            case BFFM_INITIALIZED:
                SendMessage(hWnd, BFFM_SETEXPANDED, IntPtr.Zero, lpData);
                break;
            }

            return 0;
        }

        private static IntPtr ThisPC()
        {
            IntPtr pidl = IntPtr.Zero;

            Int32 hr = SHGetKnownFolderIDList(new Guid(FOLDERID_ComputerFolder), 0, IntPtr.Zero, ref pidl);

            return pidl;
        }

        private static IntPtr PIDLFromPath(string Path)
        {
            IntPtr pidl = IntPtr.Zero;

            Int32 hr = SHILCreateFromPath(Path, ref pidl, IntPtr.Zero);

            return pidl;
        }

        public static string SelectFolder(string Description, string InitialPath, IntPtr Owner)
        {
            BROWSEINFO bi = new BROWSEINFO();

            bi.Owner = Owner;
            bi.Description = Description;
            bi.Root = ThisPC();
            bi.Flags = (UInt32)(BIF.NONEWFOLDERBUTTON | BIF.USENEWUI);
            bi.Callback = OnBrowseEvent;
            bi.lParam = PIDLFromPath(InitialPath);

            IntPtr Buffer = Marshal.AllocHGlobal(MAX_PATH * 2);
            IntPtr pidl = IntPtr.Zero;

            try {
                pidl = SHBrowseForFolder(ref bi);

                if (pidl != IntPtr.Zero &amp;&amp; SHGetPathFromIDList(pidl, Buffer)) {
                    return Marshal.PtrToStringUni(Buffer);
                } else {
                    return null;
                }
            } finally {
                if (Buffer != IntPtr.Zero) {
                    Marshal.FreeHGlobal(Buffer);
                }
                if (pidl != IntPtr.Zero) {
                    Marshal.FreeCoTaskMem(pidl);
                }
                if (bi.lParam != IntPtr.Zero) {
                    Marshal.FreeCoTaskMem(bi.lParam);
                }
                if (bi.Root != IntPtr.Zero) {
                    Marshal.FreeCoTaskMem(bi.Root);
                }
            }
        }
    }
}
</code></pre>
<p>Usage example:</p>
<pre><code>// InitialPath will be selected and expanded if it exists and is accessible to the user
string InitialPath = @&quot;D:\Downloads&quot;;
// Handle is hwnd of your owner form
string SelectedPath = SHELL32.SelectFolder(&quot;Select foobar folder&quot;, InitialPath, Handle);
// SelectedPath will contain path or null on error / cancel
</code></pre>
<p>Full error checking as well as support for starting from known folders other than <code>My Computer</code> are left as an exercise for the reader.</p>
<p>Note that your program's <code>Main()</code> has to be marked with <code>[STAThread]</code> or the dialog will not work.</p>
<p>For more details about COM initialization and allowed flag combinations see <a href="https://learn.microsoft.com/en-us/windows/win32/api/shlobj_core/nf-shlobj_core-shbrowseforfolderw" rel="nofollow noreferrer">SHBrowseForFolderW</a> API documentation.</p>

Q: Using HTML5/JavaScript to generate and save a file A: <p>Here is a tutorial to export files as ZIP:</p>
<p>Before getting started, there is a library to save files, the name of library is fileSaver.js, You can find this library here. Let's get started, Now, include the required libraries:</p>
<pre><code>&lt;script src=&quot;https://cdnjs.cloudflare.com/ajax/libs/jszip/3.1.4/jszip.min.js&quot;  type=&quot;text/javascript&quot;&gt;&lt;/script&gt;
&lt;script type=&quot;text/javascript&quot; src=&quot;https://fastcdn.org/FileSaver.js/1.1.20151003/FileSaver.js&quot; &gt;&lt;/script&gt;
</code></pre>
<p>Now copy this code and this code will download a zip file with a file hello.txt having content Hello World. If everything thing works fine, this will download a file.</p>
<pre><code>&lt;script type=&quot;text/javascript&quot;&gt;
    var zip = new JSZip();
    zip.file(&quot;Hello.txt&quot;, &quot;Hello World\n&quot;);
    zip.generateAsync({type:&quot;blob&quot;})
    .then(function(content) {
        // see FileSaver.js
        saveAs(content, &quot;file.zip&quot;);
    });
&lt;/script&gt;
</code></pre>
<p>This will download a file called file.zip.</p>

Q: Multiply 2 matrices in Javascript A: <p>Here is my solution for multiplying matrices.</p>
<p><div class="snippet" data-lang="js" data-hide="false" data-console="true" data-babel="false" data-babel-preset-react="false" data-babel-preset-ts="false">
<div class="snippet-code">
<pre class="snippet-code-js lang-js prettyprint-override"><code>function multiply(A,B){
    var resultat = new Array();
    var i = 0;
    var lignes = A.length;
    var colonnes = B[0].length;
    for(i=0;i&lt;lignes;i++){
        var t = 0;
        var a = new Array();
        for(t=0;t&lt;colonnes;t++){
            var k = 0;
            var r = 0;
            for(k=0;k&lt;B.length;k++){
                r += A[i][k]*B[k][t];
            }
            a.push(r);
        };
        resultat.push(a);
    }
    return resultat;
}

const matriceA = [[1,2,3],[4,5,6],[7,8,9]];
const matriceB = [[9,8,7],[6,5,4],[3,2,1]];

var result = multiply(matriceA,matriceB);
console.log(result);</code></pre>
